return {["scenes"]={["s2hinapre"]={{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=1,["text"]="「这里好热闹啊」",["rows"]={"「这里好热闹啊」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=2,["text"]="「这是什么活动？」",["rows"]={"「这是什么活动？」"}},{["speaker"]="hina",["portrait"]="hinan2",["line"]=3,["text"]="「那边的红白！」",["rows"]={"「那边的红白！」"}},{["speaker"]="hina",["portrait"]="hinano",["line"]=4,["text"]="「你买票了吗？」",["rows"]={"「你买票了吗？」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=5,["text"]="「键山雏？」",["rows"]={"「键山雏？」"}},{["speaker"]="hina",["portrait"]="hinan2",["line"]=6,["text"]="「没有购买门票的话，我可是不会把你放进去的哟。」",["rows"]={"「没有购买门票的话，我可是不会把你放进去","的哟。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=7,["text"]="「原来还要钱的啊……」",["rows"]={"「原来还要钱的啊……」"}},{["speaker"]="hina",["portrait"]="hinano",["line"]=8,["text"]="「你在说什么？」",["rows"]={"「你在说什么？」"}},{["speaker"]="hina",["portrait"]="hinan2",["line"]=9,["text"]="「这是我的工作。」",["rows"]={"「这是我的工作。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=10,["text"]="「工作？」",["rows"]={"「工作？」"}},{["speaker"]="hina",["portrait"]="hinaan",["line"]=11,["text"]="「既然你执意要打扰我，那就用魔法让你安静下来吧。」",["rows"]={"「既然你执意要打扰我，那就用魔法让你安静","下来吧。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=12,["text"]="「真是令人头疼。」",["rows"]={"「真是令人头疼。」"}}},["s2mystiapre"]={{["speaker"]="mystia",["portrait"]="mystian2",["line"]=1,["text"]="「号外号外！一手新闻！新鲜现拍！」",["rows"]={"「号外号外！一手新闻！新鲜现拍！」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=2,["text"]="「夜雀也被污染了吗？」",["rows"]={"「夜雀也被污染了吗？」"}},{["speaker"]="mystia",["portrait"]="mystiasp",["line"]=3,["text"]="「咦？你在说什么？」",["rows"]={"「咦？你在说什么？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=4,["text"]="「你身上的并没有很多污秽……奇怪」",["rows"]={"「你身上的并没有很多污秽……奇怪」"}},{["speaker"]="mystia",["portrait"]="mystian2",["line"]=5,["text"]="「哎呀，咱全身上下散发的都是新闻的气息！」",["rows"]={"「哎呀，咱全身上下散发的都是新闻的气息","！」"}},{["speaker"]="mystia",["portrait"]="mystian2",["line"]=6,["text"]="「来吧，接受采访！」",["rows"]={"「来吧，接受采访！」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=7,["text"]="「看来这家伙也被奇怪的东西控制了。」",["rows"]={"「看来这家伙也被奇怪的东西控制了。」"}}},["s2mamizoupre"]={{["speaker"]="mamizou",["portrait"]="mamizouno",["line"]=1,["text"]="「哎呀呀」",["rows"]={"「哎呀呀」"}},{["speaker"]="mamizou",["portrait"]="mamizouno",["line"]=2,["text"]="「这不是永远亭的公主吗？」",["rows"]={"「这不是永远亭的公主吗？」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=3,["text"]="「你是？」",["rows"]={"「你是？」"}},{["speaker"]="mamizou",["portrait"]="mamizoun2",["line"]=4,["text"]="「你好你好，俺的cn是大狸子」",["rows"]={"「你好你好，俺的cn是大狸子」"}},{["speaker"]="mamizou",["portrait"]="mamizouno",["line"]=5,["text"]="「大家都叫俺猯藏老师」",["rows"]={"「大家都叫俺猯藏老师」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=6,["text"]="「请问这里到底是在干什么」",["rows"]={"「请问这里到底是在干什么」"}},{["speaker"]="tanuki",["portrait"]="tanukin2",["line"]=7,["text"]="「这里是人里举办的漫展。」",["rows"]={"「这里是人里举办的漫展。」"}},{["speaker"]="tanuki",["portrait"]="tanukino",["line"]=8,["text"]="「老身今天受邀来当官方妆娘，替大家提供服务。」",["rows"]={"「老身今天受邀来当官方妆娘，替大家提供服","务。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=9,["text"]="「妆娘……？」",["rows"]={"「妆娘……？」"}},{["speaker"]="tanuki",["portrait"]="tanukino",["line"]=10,["text"]="「就是替别人化妆、打扮，帮她们变成自己喜欢的角色。」",["rows"]={"「就是替别人化妆、打扮，帮她们变成自己喜","欢的角色。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=11,["text"]="「原来如此……」",["rows"]={"「原来如此……」"}},{["speaker"]="kaguya",["portrait"]="kaguya21",["line"]=12,["text"]="「就是说，你就是导致所有人发生奇怪变化的凶手吧！」",["rows"]={"「就是说，你就是导致所有人发生奇怪变化的","凶手吧！」"}},{["speaker"]="tanuki",["portrait"]="tanukino",["line"]=13,["text"]="「好像有什么误会……」",["rows"]={"「好像有什么误会……」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=14,["text"]="「你亲口承认了，还想抵赖吗？」",["rows"]={"「你亲口承认了，还想抵赖吗？」"}}},["s2mamizoupost"]={{["speaker"]="tanuki",["portrait"]="tanukidp",["line"]=1,["text"]="「咳咳，嗯咳咳——」",["rows"]={"「咳咳，嗯咳咳——」"}},{["speaker"]="tanuki",["portrait"]="tanukidp",["line"]=2,["text"]="「让俺先喘口气吧。」",["rows"]={"「让俺先喘口气吧。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=3,["text"]="「还想拖延时间吗？」",["rows"]={"「还想拖延时间吗？」"}},{["speaker"]="tanuki",["portrait"]="tanukino",["line"]=4,["text"]="「老身刚才不是已经说过了吗？」",["rows"]={"「老身刚才不是已经说过了吗？」"}},{["speaker"]="tanuki",["portrait"]="tanukin2",["line"]=5,["text"]="「这里不过是人里的漫展，老身只是负责帮大家化妆罢了。」",["rows"]={"「这里不过是人里的漫展，老身只是负责帮大","家化妆罢了。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=6,["text"]="「那么，最近幻想乡里发生的那些变化，和你没有关系？」",["rows"]={"「那么，最近幻想乡里发生的那些变化，和你","没有关系？」"}},{["speaker"]="tanuki",["portrait"]="tanukino",["line"]=7,["text"]="「大概如此。老身也不知道究竟是谁在捣鬼。」",["rows"]={"「大概如此。老身也不知道究竟是谁在捣鬼","。」"}},{["speaker"]="tanuki",["portrait"]="tanukino",["line"]=8,["text"]="「不好意思让你误会了，这张能力卡牌就送给你当赔礼吧。」",["rows"]={"「不好意思让你误会了，这张能力卡牌就送给","你当赔礼吧。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=9,["text"]="「这是什么？」",["rows"]={"「这是什么？」"}},{["speaker"]="tanuki",["portrait"]="tanukino",["line"]=10,["text"]="「能够让弹幕追踪目标的卡牌。希望它能带你找到最终的答案。」",["rows"]={"「能够让弹幕追踪目标的卡牌。希望它能带你","找到最终的答案。」"}}}},["names"]={["kaguya"]="辉夜",["hina"]="“键山雏”",["mystia"]="米斯蒂娅",["mamizou"]="二岩猯藏",["tanuki"]="猯藏"},["art"]={["hinan2"]={["layers"]={{["file"]="art/face02no_d.png",["w"]=256,["h"]=64,["cx"]=128,["cy"]=64},{["file"]="art/face02n2_u.png",["w"]=256,["h"]=256,["cx"]=128,["cy"]=320}},["scale"]=1.125},["hinano"]={["layers"]={{["file"]="art/face02no_d.png",["w"]=256,["h"]=64,["cx"]=128,["cy"]=64},{["file"]="art/face02no_u.png",["w"]=256,["h"]=256,["cx"]=128,["cy"]=320}},["scale"]=1.125},["hinaan"]={["layers"]={{["file"]="art/face02no_d.png",["w"]=256,["h"]=64,["cx"]=128,["cy"]=64},{["file"]="art/face02an_u.png",["w"]=256,["h"]=256,["cx"]=128,["cy"]=320}},["scale"]=1.125},["mystian2"]={["layers"]={{["file"]="art/face_st02n2.png",["w"]=128,["h"]=256,["x"]=1,["y"]=1,["cw"]=126,["ch"]=254,["cx"]=63,["cy"]=254}},["scale"]=1.4173228346456692},["mystiasp"]={["layers"]={{["file"]="art/face_st02sp.png",["w"]=128,["h"]=256,["x"]=1,["y"]=1,["cw"]=126,["ch"]=254,["cx"]=63,["cy"]=254}},["scale"]=1.4173228346456692},["mamizouno"]={["layers"]={{["file"]="art/face07bs.png",["w"]=19